import sys
def recover(cipher,known,keylen):
 k=[None]*keylen
 for i,b in enumerate(known):
  v=cipher[i]^b; j=i%keylen
  if k[j] is not None and k[j]!=v: raise ValueError('inconsistent known plaintext')
  k[j]=v
 return bytes(x if x is not None else 0 for x in k),k
def xor(data,key): return bytes(b^key[i%len(key)] for i,b in enumerate(data))
# usage: hex_cipher known_text keylen
c=bytes.fromhex(sys.argv[1]); known=sys.argv[2].encode(); n=int(sys.argv[3]); kb,slots=recover(c,known,n); print('key slots:',slots); print('key:',kb); print('plain:',xor(c,kb))
